import { Mail } from "lucide-react";

export function ContactsEmptyState({
  noMatches = false,
}: {
  noMatches?: boolean;
}) {
  return (
    <div className="hover-card rounded-[var(--appearance-radius,24px)] border border-dashed border-[var(--contacts-strong)] bg-[image:var(--appearance-decoration,radial-gradient(60%_80%_at_50%_0%,var(--color-contactsemptystate-detail-1),transparent))] px-6 py-[52px] text-center">
      {!noMatches && (
        <div className="workspace-icon-tile mx-auto mb-4 grid size-14 place-items-center rounded-[var(--appearance-radius,18px)] bg-[image:var(--contacts-gradient)] text-[var(--appearance-on-primary,var(--color-contactsemptystate-detail-2))] shadow-[var(--appearance-shadow,0_0_36px_var(--color-contactsemptystate-shadow-1))]">
          <Mail aria-hidden="true" size={26} />
        </div>
      )}
      <h2 className="text-[22px] font-extrabold tracking-[-.03em]">
        {noMatches ? "No matches" : "Meet your shortlist"}
      </h2>
      <p className="mt-1.5 text-sm text-[var(--contacts-muted)]">
        {noMatches
          ? "Try a different name, email, or company."
          : "Add your first contact, or import a list below."}
      </p>
    </div>
  );
}
